import { useState, useEffect, useMemo, useRef } from "react";

/* ───────── DEMO LOGIC (fake data — replace makeResult() with your API call) ───────── */
const STEPS = [
  "Checking where it came from",
  "Looking for signs of AI",
  "Searching the web for copies",
  "Preparing your result",
];

const COPIES = {
  REAL: [
    { site: "reuters.com", date: "2 Oct 2026", note: "Original publisher" },
    { site: "bbc.co.uk", date: "3 Oct 2026", note: "Used with credit" },
  ],
  UNSURE: [
    { site: "newsarchive.org", date: "11 Aug 2026", note: "Older, sharper version" },
    { site: "reddit.com", date: "12 Aug 2026", note: "Larger copy" },
    { site: "t.me/forwards", date: "12 Oct 2026", note: "Re-saved with a caption added" },
    { site: "facebook.com", date: "13 Oct 2026", note: "Re-saved with a logo added" },
  ],
  FAKE: [],
};

const LOOK = {
  FAKE: {
    title: "Very likely AI-generated",
    text: "It may look real, but our checks found patterns that real cameras don't produce.",
    ring: "border-rose-400/40", color: "text-rose-300", bg: "bg-rose-400/10",
  },
  REAL: {
    title: "Looks real",
    text: "It carries proof from the camera that took it, and it appears at trusted sources.",
    ring: "border-emerald-400/40", color: "text-emerald-300", bg: "bg-emerald-400/10",
  },
  UNSURE: {
    title: "We're not sure",
    text: "Our checks disagree. This may be an edited or much-shared photo, so we won't guess.",
    ring: "border-amber-400/40", color: "text-amber-300", bg: "bg-amber-400/10",
  },
};

/* Example photos are real public-domain photographs. Verdicts are scripted for the demo. */
const EXAMPLES = [
  { label: "Gym selfie", name: "gym_selfie.jpg", preset: "FAKE", p: 0.93, cues: ["Skin looks unnaturally smooth, with no pores or fine texture.", "Gym machines in the background blur into each other.", "Face lighting doesn't match the bright lights behind it."], src: "data:image/jpeg;base64," },
  { label: "Beach portrait", name: "beach_portrait.jpg", preset: "FAKE", p: 0.97, cues: ["A small AI-tool sparkle mark sits in the bottom-right corner.", "Hands and shirt folds are smoother than a real camera captures.", "Lighting on the face and rock is too perfect to be natural."], src: "data:image/jpeg;base64," },
  { label: "Ancient temple", name: "temple_sunset.jpg", preset: "FAKE", p: 0.91, cues: ["The sky and light are more dramatic than a real sunset.", "Stone textures repeat in odd patterns.", "Buildings in the distance are soft and slightly distorted."], src: "data:image/jpeg;base64," },
  { label: "Garden portrait", name: "garden_portrait.jpg", preset: "FAKE", p: 0.95, cues: ["The dress fabric melts into the grass at its edges.", "The hand holding the dress looks soft and unclear.", "The glow around the hair is too even to be natural sunlight."], src: "data:image/jpeg;base64," },
  { label: "Press portrait", name: "astronaut_press_photo.jpg", preset: "REAL", src: "data:image/jpeg;base64," },
  { label: "Cafe promo shot", name: "cafe_promo_shot.jpg", preset: "FAKE", src: "data:image/jpeg;base64," },
  { label: "Viral cat forward", name: "viral_cat_forward.jpg", preset: "UNSURE", src: "data:image/jpeg;base64," },
  { label: "Tourism banner", name: "tourism_banner.jpg", preset: "FAKE", src: "data:image/jpeg;base64," },
  { label: "Team headshot", name: "team_headshot.jpg", preset: "REAL", p: 0.04, cues: ["Skin shows natural pores, fine lines and small uneven tones.", "Hair strands, earrings and necklace are sharp and consistent.", "Window light matches the soft shadows on the face."], copies: [{"site": "company-website.com", "date": "4 Sep 2026", "note": "Original team page"}, {"site": "social-media.com", "date": "6 Sep 2026", "note": "Used as a profile photo"}], src: "data:image/jpeg;base64," },
  { label: "Zoo vulture", name: "zoo_vulture.jpg", preset: "REAL", p: 0.06, cues: ["Feathers show natural, uneven detail down to single strands.", "Shadows on the bird and tree trunk match the light in the scene.", "The photographer's credit mark is visible in the top-left corner."], copies: [{"site": "zoo-gallery.com", "date": "20 Sep 2026", "note": "Original post by the photographer"}, {"site": "instagram.com", "date": "21 Sep 2026", "note": "Shared with credit"}], src: "data:image/jpeg;base64," },
];

const toFile = (e) => ({ url: e.src, name: e.name, size: e.src.length, isVideo: false, preset: e.preset, p: e.p, cues: e.cues, copies: e.copies });
const PAST = [["team_headshot.jpg", "14 Oct 2026"], ["zoo_vulture.jpg", "14 Oct 2026"], ["astronaut_press_photo.jpg", "14 Oct 2026"], ["viral_cat_forward.jpg", "13 Oct 2026"], ["cafe_promo_shot.jpg", "11 Oct 2026"], ["tourism_banner.jpg", "8 Oct 2026"]];
const BAR = { FAKE: "bg-rose-400", REAL: "bg-emerald-400", UNSURE: "bg-amber-400" };

const hash = (s) => { let h = 0; for (const c of s) h = (h * 31 + c.charCodeAt(0)) >>> 0; return h; };

// Same file always gives the same result, so a demo is repeatable.
function makeResult(file, force) {
  const h = hash(file.name + file.size);
  const v = force !== "auto" ? force : file.preset || ["FAKE", "REAL", "UNSURE"][h % 3];
  const r = (h % 100) / 100;
  const p = file.p ?? (v === "FAKE" ? 0.88 + r * 0.1 : v === "REAL" ? 0.02 + r * 0.1 : 0.4 + r * 0.25);
  const copies = file.copies || COPIES[v];
  const checks = [
    v === "REAL"
      ? { s: "ok", t: "Where it came from", d: "Verified: signed by the camera that took it." }
      : { s: "warn", t: "Where it came from", d: v === "FAKE" ? "No proof of origin. Nothing records who made this file." : "Its origin record has been removed, which often happens when photos are shared." },
    v === "FAKE"
      ? { s: "bad", t: "Signs of AI", d: "Found patterns typical of AI image makers." }
      : v === "REAL"
      ? { s: "ok", t: "Signs of AI", d: "No AI patterns found." }
      : { s: "warn", t: "Signs of AI", d: "A few unusual patterns, but not clear enough to call." },
    copies.length === 0
      ? { s: "warn", t: "Found online", d: "Nothing like it exists online. A real photo usually leaves a trail." }
      : { s: v === "REAL" ? "ok" : "warn", t: "Found online", d: `${copies.length} copies found. Earliest: ${copies[0].site}, ${copies[0].date}.` },
  ];
  (file.cues || []).forEach((d) => checks.push({ s: v === "REAL" ? "ok" : "bad", t: v === "REAL" ? "What looks natural" : "What gave it away", d }));
  return { v, p, conf: v === "REAL" ? 1 - p : p, copies, checks };
}

/* ───────── SMALL PIECES ───────── */
const MARK = { ok: ["✓", "text-emerald-300 bg-emerald-400/10"], bad: ["✕", "text-rose-300 bg-rose-400/10"], warn: ["!", "text-amber-300 bg-amber-400/10"] };

const Media = ({ file, scanning }) => (
  <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-black/40">
    {file.isVideo
      ? <video src={file.url} controls className="max-h-[28rem] w-full object-contain" />
      : <img src={file.url} alt="Your upload" className="max-h-[28rem] w-full object-contain" />}
    {scanning && <div className="scanline pointer-events-none absolute inset-x-0 h-16 bg-gradient-to-b from-transparent via-cyan-300/30 to-transparent" />}
  </div>
);

const Meter = ({ p }) => (
  <div>
    <div className="relative h-3 rounded-full" style={{ background: "linear-gradient(90deg,#34d399 0%,#34d399 20%,#fbbf24 45%,#fbbf24 70%,#fb7185 85%)" }}>
      <div className="absolute -top-1.5 h-6 w-1.5 rounded bg-white shadow-lg" style={{ left: `calc(${p * 100}% - 3px)` }} />
    </div>
    <div className="mt-1.5 flex justify-between text-xs text-slate-400"><span>Real</span><span>Not sure</span><span>AI-generated</span></div>
  </div>
);

/* ───────── APP ───────── */
export default function TraceAI() {
  const [file, setFile] = useState(null);     // { url, name, size, isVideo }
  const [step, setStep] = useState(0);        // 0..4 (4 = finished)
  const [force, setForce] = useState("auto"); // demo helper
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [history, setHistory] = useState(() => PAST.map(([n, d]) => ({ ...toFile(EXAMPLES.find((e) => e.name === n)), date: d })));
  const [drag, setDrag] = useState(false);
  const input = useRef(null);

  const result = useMemo(() => (file ? file.fin || makeResult(file, force) : null), [file, force]);
  const scanning = file && step < 4;

  useEffect(() => {
    if (!scanning) return;
    const t = setTimeout(() => setStep((s) => s + 1), 900);
    return () => clearTimeout(t);
  }, [scanning, step]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 2500);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    if (file && step === 4 && !file.fin) setHistory((h) => (h.some((x) => x.url === file.url) ? h : [{ ...file, date: "Today", fin: result }, ...h]));
  }, [file, step, result]);

  const pick = (f) => {
    if (!f) return;
    if (!/^(image|video)\//.test(f.type)) { setError("Please choose a photo or a video."); return; }
    setError("");
    setFile({ url: URL.createObjectURL(f), name: f.name, size: f.size, isVideo: f.type.startsWith("video") });
    setStep(0);
  };
  const reset = () => { setFile(null); setStep(0); };

  const tryExample = (e) => {
    setError(""); setForce("auto");
    setFile(toFile(e));
    setStep(0);
  };

  const openPast = (h) => { setError(""); setForce("auto"); setFile(h); setStep(4); };

  const download = () => {
    const L = LOOK[result.v];
    const txt = [
      "TRACEAI REPORT", `File: ${file.name}`, `Date: 15 Oct 2026`, `Result: ${L.title}`,
      `Confidence: ${Math.round(result.conf * 100)}%`, "", ...result.checks.map((c) => `- ${c.t}: ${c.d}`),
      "", "Copies found online:", ...(result.copies.length ? result.copies.map((c) => `- ${c.site} (${c.date}) ${c.note}`) : ["- none"]),
    ].join("\n");
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([txt], { type: "text/plain" }));
    a.download = "traceai-report.txt"; a.click();
    setToast("Report downloaded");
  };

  const L = result && LOOK[result.v];

  return (
    <div className="min-h-screen bg-[#0c1018] text-slate-200">
      <style>{`@keyframes scan{0%{top:-4rem}100%{top:100%}} .scanline{animation:scan 1.6s linear infinite}`}</style>

      <header className="border-b border-white/10">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-4">
          <div>
            <p className="text-xl font-bold tracking-tight text-white">Trace<span className="text-cyan-300">AI</span></p>
            <p className="text-xs text-slate-400">Don't trust your eyes. Trace the truth.</p>
          </div>
          {file && <button onClick={reset} className="rounded-lg border border-white/15 px-3 py-1.5 text-sm text-slate-300 hover:bg-white/5">Check another</button>}
        </div>
      </header>

      <div className="mx-auto flex max-w-7xl flex-col gap-6 px-4 lg:flex-row">
      <main className="min-w-0 flex-1 py-8">
        {/* 1 · UPLOAD */}
        {!file && (
          <div className="mx-auto max-w-2xl text-center">
            <h1 className="text-3xl font-bold text-white sm:text-4xl">Is this photo real?</h1>
            <p className="mt-3 text-slate-400">Upload a photo or video. In a few seconds we tell you if it looks real, fake, or if we can't be sure.</p>
            <div
              onClick={() => input.current.click()}
              onDragOver={(e) => { e.preventDefault(); setDrag(true); }}
              onDragLeave={() => setDrag(false)}
              onDrop={(e) => { e.preventDefault(); setDrag(false); pick(e.dataTransfer.files[0]); }}
              className={`mt-8 cursor-pointer rounded-2xl border-2 border-dashed px-6 py-16 transition ${drag ? "border-cyan-300 bg-cyan-300/10" : "border-white/20 bg-[#141926] hover:border-cyan-300/60"}`}
            >
              <p className="text-lg font-semibold text-white">Drop your photo here</p>
              <p className="mt-1 text-sm text-slate-400">or click to choose a file</p>
              <span className="mt-5 inline-block rounded-lg bg-cyan-400 px-5 py-2.5 text-sm font-semibold text-slate-900">Choose photo or video</span>
              <input ref={input} type="file" accept="image/*,video/*" className="hidden" onChange={(e) => pick(e.target.files[0])} />
            </div>
            {error && <p className="mt-3 text-sm text-rose-300">{error}</p>}
            <p className="mt-4 text-xs text-slate-500">Your file stays in your browser in this demo. Nothing is uploaded.</p>

            <div className="mt-10">
              <p className="mb-3 text-sm text-slate-400">No photo handy? Try an example</p>
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                {EXAMPLES.map((e) => (
                  <button key={e.name} onClick={() => tryExample(e)} className="overflow-hidden rounded-xl border border-white/10 bg-[#141926] text-left transition hover:border-cyan-300/60">
                    <img src={e.src} alt={e.label} className="h-28 w-full object-cover" />
                    <span className="block px-3 py-2 text-xs text-slate-300">{e.label}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* 2 · CHECKING */}
        {file && scanning && (
          <div className="mx-auto grid max-w-4xl items-center gap-6 md:grid-cols-2">
            <Media file={file} scanning />
            <div>
              <h2 className="text-2xl font-bold text-white">Checking your {file.isVideo ? "video" : "photo"}…</h2>
              <ul className="mt-5 space-y-3">
                {STEPS.map((t, i) => (
                  <li key={t} className="flex items-center gap-3 text-sm">
                    <span className={`grid h-6 w-6 place-items-center rounded-full text-xs font-bold ${i < step ? "bg-cyan-400 text-slate-900" : i === step ? "animate-pulse bg-cyan-400/30 text-cyan-100" : "bg-white/5 text-slate-500"}`}>{i < step ? "✓" : ""}</span>
                    <span className={i <= step ? "text-slate-100" : "text-slate-500"}>{t}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        )}

        {/* 3 · RESULT */}
        {file && !scanning && (
          <div className="grid gap-6 md:grid-cols-2">
            <div className="space-y-3">
              <Media file={file} />
              <p className="truncate text-xs text-slate-500">{file.name}</p>
            </div>

            <div className="space-y-5">
              <div className={`rounded-2xl border p-5 ${L.ring} ${L.bg}`}>
                <p className="text-sm text-slate-400">Our result</p>
                <p className={`text-3xl font-bold ${L.color}`}>{L.title}</p>
                <p className="mt-2 text-sm text-slate-200">{L.text}</p>
                <p className="mt-3 text-sm text-slate-300">AI-generated likelihood: <b className={`text-xl ${L.color}`}>{Math.round(result.p * 100)}%</b></p>
                <div className="mt-5">
                  <p className="mb-2 text-sm text-slate-300">
                    {result.v === "UNSURE" ? "How sure are we? Not very, " : "How sure are we? "}
                    <b className="text-white">{Math.round(result.conf * 100)}%</b>
                  </p>
                  <Meter p={result.p} />
                </div>
              </div>

              <section className="rounded-2xl border border-white/10 bg-[#141926] p-5">
                <h3 className="mb-3 font-semibold text-white">Why we think so</h3>
                <ul className="space-y-3">
                  {result.checks.map((c) => (
                    <li key={c.t + c.d} className="flex gap-3">
                      <span className={`grid h-6 w-6 shrink-0 place-items-center rounded-full text-xs font-bold ${MARK[c.s][1]}`}>{MARK[c.s][0]}</span>
                      <div><p className="text-sm font-medium text-slate-100">{c.t}</p><p className="text-sm text-slate-400">{c.d}</p></div>
                    </li>
                  ))}
                </ul>
              </section>
            </div>

            <section className="rounded-2xl border border-white/10 bg-[#141926] p-5">
              <h3 className="font-semibold text-white">Where else it appears</h3>
              {result.copies.length === 0 ? (
                <p className="mt-2 text-sm text-slate-400">We couldn't find this anywhere online.</p>
              ) : (
                <ol className="relative mt-4 ml-2 border-l border-white/15">
                  {result.copies.map((c, i) => (
                    <li key={c.site} className="mb-4 ml-5 last:mb-0">
                      <span className={`absolute -left-[7px] h-3.5 w-3.5 rounded-full ${i === 0 ? "bg-cyan-300" : "bg-slate-500"}`} />
                      <p className="text-xs text-slate-400">{c.date}{i === 0 && <b className="ml-2 text-cyan-300">First seen</b>}</p>
                      <p className="text-sm font-medium text-slate-100">{c.site}</p>
                      <p className="text-sm text-slate-400">{c.note}</p>
                    </li>
                  ))}
                </ol>
              )}
            </section>

            <section className="rounded-2xl border border-white/10 bg-[#141926] p-5">
              <h3 className="font-semibold text-white">What you can do</h3>
              <div className="mt-3 space-y-2">
                {result.v !== "REAL" && (
                  <>
                    <button onClick={() => setToast("Report sent (demo)")} className="w-full rounded-lg bg-cyan-400 px-4 py-2.5 text-sm font-semibold text-slate-900 hover:bg-cyan-300">Report this {file.isVideo ? "video" : "photo"}</button>
                    <button onClick={() => setToast("Removal request sent (demo)")} className="w-full rounded-lg border border-rose-400/40 px-4 py-2.5 text-sm font-semibold text-rose-200 hover:bg-rose-400/10">Ask for it to be removed</button>
                  </>
                )}
                <button onClick={download} className={`w-full rounded-lg px-4 py-2.5 text-sm font-semibold ${result.v === "REAL" ? "bg-cyan-400 text-slate-900 hover:bg-cyan-300" : "border border-white/15 text-slate-200 hover:bg-white/5"}`}>Download my report</button>
                <button onClick={reset} className="w-full rounded-lg px-4 py-2.5 text-sm text-slate-400 hover:text-white">Check another</button>
              </div>
            </section>
          </div>
        )}
      </main>

      <aside className="w-full shrink-0 py-8 lg:w-80">
        <div className="rounded-2xl border border-white/10 bg-[#141926] p-4 lg:sticky lg:top-4">
          <h3 className="font-semibold text-white">Previously checked</h3>
          <p className="mb-3 text-xs text-slate-400">Tap one to see its details.</p>
          <ul className="max-h-[75vh] space-y-2 overflow-y-auto">
            {history.map((h) => {
              const r = h.fin || makeResult(h, "auto");
              return (
                <li key={h.url}>
                  <button onClick={() => openPast(h)} className={`flex w-full gap-3 rounded-xl border p-2 text-left transition ${file && file.url === h.url ? "border-cyan-300/60 bg-cyan-300/5" : "border-white/10 hover:border-white/30"}`}>
                    {h.isVideo ? <div className="grid h-14 w-14 shrink-0 place-items-center rounded-lg bg-white/5 text-slate-400">▶</div> : <img src={h.url} alt="" className="h-14 w-14 shrink-0 rounded-lg object-cover" />}
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-sm text-slate-100">{h.name}</p>
                      <p className="text-xs text-slate-500">{h.date} · {LOOK[r.v].title}</p>
                      <div className="mt-1.5 flex items-center gap-2">
                        <div className="h-1.5 flex-1 rounded bg-white/10"><div className={`h-1.5 rounded ${BAR[r.v]}`} style={{ width: `${Math.round(r.p * 100)}%` }} /></div>
                        <span className="text-xs font-semibold text-slate-200">{Math.round(r.p * 100)}% AI</span>
                      </div>
                    </div>
                  </button>
                </li>
              );
            })}
          </ul>
        </div>
      </aside>
      </div>

      <footer className="mx-auto max-w-7xl px-4 pb-8">
        <div className="flex flex-wrap items-center gap-2 border-t border-white/10 pt-4 text-xs text-slate-500">
          <span>Demo mode. Results are simulated. Force a result:</span>
          {[["auto", "Auto"], ["FAKE", "Fake"], ["REAL", "Real"], ["UNSURE", "Not sure"]].map(([k, t]) => (
            <button key={k} onClick={() => setForce(k)} className={`rounded-full border px-2.5 py-0.5 ${force === k ? "border-cyan-300/60 text-cyan-200" : "border-white/10 hover:text-slate-300"}`}>{t}</button>
          ))}
        </div>
      </footer>

      {toast && <div className="fixed bottom-6 left-1/2 -translate-x-1/2 rounded-lg border border-cyan-400/40 bg-[#141926] px-4 py-2 text-sm text-cyan-100 shadow-xl">{toast}</div>}
    </div>
  );
}